cd /tmp/vally-eval-trial-TlLRIm && P=.copilot-tracking/skraft-plans/pricing && D=2026-11-10 && mkdir -p $P/features $P/details/$D $P/evidence/$D/discount tests/CheckoutPricing.UnitTest/Features/LoyaltyDiscount
cat > $P/features/pricing-loyalty-discount.feature <<'EOF'
@loyalty-discount
Feature: Loyalty discount at checkout
  As a returning customer
  I want my loyalty tier reflected in the checkout total
  So that the price I see rewards my history with the brand

  # SETTLED: the four scenarios below are approved (ac.md AC-1..AC-4).
  # NOT SETTLED: Platinum has no agreed reduction, so it has no scenario here.
  # See the "Open decisions" section at the end of this file.

  @happy-path @smoke
  Scenario: Bronze customer is charged the Bronze price
    Given a returning customer in the Bronze tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 9500 cents

  @happy-path
  Scenario: Silver customer is charged the Silver price
    Given a returning customer in the Silver tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 9000 cents

  @happy-path
  Scenario: Gold customer is charged the Gold price
    Given a returning customer in the Gold tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 8500 cents

  @edge-case
  Scenario: Bronze customer's reduction lands on a whole cent in the customer's favour
    Given a returning customer in the Bronze tier
    When a basket subtotal of 7 cents is priced
    Then the customer is charged 7 cents

  # OPEN DECISIONS (no scenario, no expected value, deliberately):
  #   - Platinum tier: the business has not agreed a reduction. Arriving next quarter,
  #     out of scope for milestone M1. Owner: DISCUSS / business. Add a scenario only
  #     once an observable example (tier, subtotal, charged amount) is approved.
EOF
cat > tests/CheckoutPricing.UnitTest/Features/LoyaltyDiscount/LoyaltyDiscountAcceptanceTests.cs <<'EOF'
using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Features.LoyaltyDiscount;

public class LoyaltyDiscountAcceptanceTests
{
    // Bronze customer is charged the Bronze price
    [Fact]
    public void Bronze_customer_is_charged_the_Bronze_price()
    {
        var pricing = new CalculateLoyaltyDiscount();

        var quote = pricing.Handle(new CalculateLoyaltyDiscountQuery(10000, LoyaltyTier.Bronze));

        Assert.Equal(9500, quote.TotalCents);
    }
}
EOF
dotnet test tests/CheckoutPricing.UnitTest --filter "FullyQualifiedName~LoyaltyDiscountAcceptanceTests" > $P/evidence/$D/discount/acceptance-red.stdout 2>&1; echo $? > $P/evidence/$D/discount/acceptance-red.exit; git rev-parse HEAD > $P/evidence/$D/discount/acceptance-red.rev; cat $P/evidence/$D/discount/acceptance-red.exit $P/evidence/$D/discount/acceptance-red.rev; tail -25 $P/evidence/$D/discount/acceptance-red.stdout

